<?php
declare(strict_types=1);
require dirname(__DIR__).'/src/Core.php';
use Wams\Core;
session_name('WAMSSESSID');session_start(['cookie_httponly'=>true,'cookie_samesite'=>'Lax','cookie_secure'=>isset($_SERVER['HTTPS'])]);
$c=new Core();$p=(string)($_GET['p']??'home');$error='';
function h(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function go(string $p='home'):never{header('Location: ?p='.rawurlencode($p));exit;}
try{
 if(!$c->installed()&&$p!=='setup')go('setup');
 if($p==='setup'&&$_SERVER['REQUEST_METHOD']==='POST'){$c->migrate();if((int)$c->db->query('SELECT COUNT(*) FROM users')->fetchColumn()===0){$id=$c->id();$s=$c->db->prepare('INSERT INTO users VALUES(?,?,?,?,1,1,NULL,0,?)');$s->execute([$id,trim($_POST['username']),trim($_POST['email']),password_hash($_POST['password'],PASSWORD_ARGON2ID),gmdate('c')]);}go('login');}
 if($p==='login'&&$_SERVER['REQUEST_METHOD']==='POST'){if($c->login(trim($_POST['login']),$_POST['password']))go();$error='Anmeldung fehlgeschlagen.';}
 if($p==='logout'){session_destroy();go('login');}
 if(!in_array($p,['setup','login'],true))$u=$c->requireLogin();
 if(isset($u)&&$_SERVER['REQUEST_METHOD']==='POST'){$c->checkCsrf();
  if($p==='tenant-new'&&$u['is_global']){$s=$c->db->prepare('INSERT INTO tenants VALUES(?,?,NULL,?)');$s->execute([$c->id(),trim($_POST['name']),gmdate('c')]);$c->audit('tenant.create',['name'=>trim($_POST['name'])]);go('tenants');}
  if($p==='user-new'&&$u['is_global']){$id=$c->id();$s=$c->db->prepare('INSERT INTO users VALUES(?,?,?,?,0,1,NULL,0,?)');$s->execute([$id,trim($_POST['username']),trim($_POST['email']),password_hash($_POST['password'],PASSWORD_ARGON2ID),gmdate('c')]);foreach($_POST['tenants']??[] as $tid){$q=$c->db->prepare('INSERT OR IGNORE INTO user_tenants VALUES(?,?)');$q->execute([$id,$tid]);}$c->audit('user.create',['user'=>$id]);go('users');}
  if($p==='group-new'){$tid=(string)$_POST['tenant'];if(!$c->canTenant($u['id'],$tid))throw new RuntimeException('Kein Tenant-Zugriff.');$s=$c->db->prepare('INSERT INTO groups VALUES(?,?,?,NULL)');$s->execute([$c->id(),$tid,trim($_POST['name'])]);go('groups');}
  if($p==='app-install'){$tid=(string)$_POST['tenant'];if(!$c->canTenant($u['id'],$tid))throw new RuntimeException('Kein Tenant-Zugriff.');$cfg=json_decode($_POST['config']?:'{}',true);if(!is_array($cfg))throw new RuntimeException('Konfiguration ist kein gültiges JSON.');$c->installApp($tid,(string)$_POST['app'],trim($_POST['name']),$cfg);go('apps');}
 }
}catch(Throwable $e){$error=$e->getMessage();}
?><!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>WAMS</title><link rel="stylesheet" href="assets/style.css"></head><body>
<header><strong>WAMS</strong><?php if(isset($u)):?><nav><a href="?p=home">Launcher</a><a href="?p=apps">Apps</a><a href="?p=tenants">Tenants</a><a href="?p=groups">Gruppen</a><?php if($u['is_global']):?><a href="?p=users">Benutzer</a><a href="?p=audit">Audit</a><?php endif?><a href="?p=logout">Abmelden</a></nav><?php endif?></header><main class="wrap"><?php if($error):?><div class="error"><?=h($error)?></div><?php endif?>
<?php if($p==='setup'):?><section class="card"><h1>WAMS-Ersteinrichtung</h1><p>Der erste Benutzer wird globaler Administrator.</p><form method="post"><label>Benutzername</label><input name="username" required><label>E-Mail</label><input type="email" name="email" required><label>Passwort</label><input type="password" name="password" minlength="12" required><p><button>Installation abschließen</button></p></form></section>
<?php elseif($p==='login'):?><section class="card"><h1>Anmeldung</h1><form method="post"><label>Benutzername oder E-Mail</label><input name="login" required><label>Passwort</label><input type="password" name="password" required><p><button>Anmelden</button></p></form></section>
<?php elseif($p==='home'):$ts=$c->tenants($u['id']);?><h1>App Launcher</h1><div class="grid"><?php foreach($ts as $t):$s=$c->db->prepare('SELECT * FROM app_instances WHERE tenant_id=?');$s->execute([$t['id']]);foreach($s as $i):?><section class="card"><div class="muted"><?=h($t['name'])?></div><h2><?=h($i['name'])?></h2><code><?=h($i['app_id'])?> <?=h($i['version'])?></code></section><?php endforeach;endforeach?></div><p class="muted">Nicht als Katalog-App markierte Repository-Beispiele erscheinen hier nicht.</p>
<?php elseif($p==='tenants'):$ts=$c->tenants($u['id']);?><h1>Tenants</h1><?php if($u['is_global']):?><section class="card"><form method="post" action="?p=tenant-new"><input type="hidden" name="csrf" value="<?=h($c->csrf())?>"><label>Neue Organisation</label><input name="name" required><p><button>Anlegen</button></p></form></section><?php endif?><section class="card"><table><tr><th>Name</th><th>ID</th></tr><?php foreach($ts as $t):?><tr><td><?=h($t['name'])?></td><td><code><?=h($t['id'])?></code></td></tr><?php endforeach?></table></section>
<?php elseif($p==='users'&&$u['is_global']):$ts=$c->tenants($u['id']);?><h1>Benutzer</h1><section class="card"><form method="post" action="?p=user-new"><input type="hidden" name="csrf" value="<?=h($c->csrf())?>"><div class="grid"><div><label>Benutzername</label><input name="username" required></div><div><label>E-Mail</label><input type="email" name="email" required></div><div><label>Startpasswort</label><input type="password" name="password" minlength="12" required></div></div><label>Tenants</label><?php foreach($ts as $t):?><label><input style="width:auto" type="checkbox" name="tenants[]" value="<?=h($t['id'])?>"> <?=h($t['name'])?></label><?php endforeach?><p><button>Anlegen</button></p></form></section><section class="card"><table><tr><th>Benutzer</th><th>E-Mail</th><th>Global</th></tr><?php foreach($c->db->query('SELECT * FROM users ORDER BY username') as $x):?><tr><td><?=h($x['username'])?></td><td><?=h($x['email'])?></td><td><?=$x['is_global']?'Ja':'Nein'?></td></tr><?php endforeach?></table></section>
<?php elseif($p==='groups'):$ts=$c->tenants($u['id']);?><h1>Gruppen</h1><section class="card"><form method="post" action="?p=group-new"><input type="hidden" name="csrf" value="<?=h($c->csrf())?>"><label>Tenant</label><select name="tenant"><?php foreach($ts as $t):?><option value="<?=h($t['id'])?>"><?=h($t['name'])?></option><?php endforeach?></select><label>Name</label><input name="name" required><p><button>Anlegen</button></p></form></section>
<?php elseif($p==='apps'):$ts=$c->tenants($u['id']);$cat=$c->catalog();?><h1>Apps</h1><section class="card"><form method="post" action="?p=app-install"><input type="hidden" name="csrf" value="<?=h($c->csrf())?>"><label>Tenant</label><select name="tenant"><?php foreach($ts as $t):?><option value="<?=h($t['id'])?>"><?=h($t['name'])?></option><?php endforeach?></select><label>App</label><select name="app"><?php foreach($cat as $a):?><option value="<?=h($a['appId'])?>"><?=h($a['name'])?> <?=h($a['version'])?></option><?php endforeach?></select><label>Instanzname</label><input name="name" required><label>App-Konfiguration (JSON)</label><textarea name="config">{}</textarea><p><button>Installieren</button></p></form></section><?php if(!$cat):?><div class="notice">Keine für den Katalog freigegebene App vorhanden. Die Example Application ist absichtlich nur eine nicht abrufbare Entwickler-Vorlage.</div><?php endif?>
<?php elseif($p==='audit'&&$u['is_global']):?><h1>Audit</h1><section class="card"><table><tr><th>Zeit</th><th>Ereignis</th><th>Daten</th></tr><?php foreach($c->db->query('SELECT * FROM audit ORDER BY created_at DESC LIMIT 200') as $a):?><tr><td><?=h($a['created_at'])?></td><td><?=h($a['event'])?></td><td><code><?=h($a['data'])?></code></td></tr><?php endforeach?></table></section>
<?php else:?><div class="error">Ansicht nicht gefunden oder nicht erlaubt.</div><?php endif?></main></body></html>
